    });

    it("selects next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [line("a", 100, 1, 501)]; // 501g > 500g → 2000g bracket
      expect(calc.computeShippingCents(lines, 100)).toBe(700);
    });

    it("selects last bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [line("a", 100, 1, 5000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2000);
      const lines = [line("a", 100, 1, 6000)]; // 6000g > 5000g
      expect(calc.computeShippingCents(lines, 100)).toBe(2000);
    });

    it("falls back to last bracket cost when no overflow specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [line("a", 100, 1, 6000)];
      expect(calc.computeShippingCents(lines, 100)).toBe(1200);
    });

    it("handles unsorted bracket input correctly", () => {
      const unsorted = [
        { upToGrams: 2000, costCents: 700 },
        { upToGrams: 500, costCents: 300 },
      ];
      const calc = new WeightBasedShippingCalculator(unsorted);
      const lines = [line("a", 100, 1, 400)]; // 400g → 500g bracket
      expect(calc.computeShippingCents(lines, 100)).toBe(300);
    });

    it("sums weight across multiple lines", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      const lines = [
        line("a", 100, 2, 300), // 600g
        line("b", 200, 1, 500), // 500g → total 1100g
      ];
      expect(calc.computeShippingCents(lines, 0)).toBe(700);
    });
  });
});

