import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const mkProduct = (
  id: string,
  priceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

// ── Cart line management ───────────────────────────────────────────

describe("Cart line management", () => {
  it("starts with 0 items and empty totals", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("add() inserts a new line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
    expect(cart.totals().subtotalCents).toBe(2000);
  });

  it("add() merges quantity for the same product", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5000);
  });

  it("add() rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 100), -1)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 100), 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unit price", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("remove() deletes an existing product and returns true", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes line quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5000);
  });

  it("updateQuantity(0) removes the line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 3)).toThrow("not in the cart");
  });

  it("updateQuantity() rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear() removes all lines", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("b", 500), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("snapshot() returns a deep copy", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const snap = cart.snapshot();
    // Mutating the snapshot should not affect the cart
    (snap as any)[0].quantity = 999;
    (snap as any)[0].product.unitPriceCents = 1;
    expect(cart.totals().subtotalCents).toBe(2000);
    expect(cart.itemCount).toBe(2);
  });
});

// ── Pricing pipeline ───────────────────────────────────────────────

describe("Cart pricing pipeline", () => {
  it("applies subtotal → discount → tax → shipping in order", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };

    const cart = new Cart({
      discountPolicy,
      taxCalculator,
      shippingCalculator,
      region: "US-CA",
    });

    cart.add(mkProduct("a", 1000), 1); // subtotal = 1000
    const t = cart.totals();

    // discount receives subtotal
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
    // tax receives discounted subtotal (1000 - 200 = 800)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    // shipping receives lines and discounted subtotal
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );

    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(200);
    expect(t.taxCents).toBe(80);
    expect(t.shippingCents).toBe(500);
    // total = discounted subtotal + tax + shipping = 800 + 80 + 500
    expect(t.totalCents).toBe(1380);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(mkProduct("a", 500), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(500); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negativeDiscount: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart = new Cart({ discountPolicy: negativeDiscount });
    cart.add(mkProduct("a", 500), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.totalCents).toBe(500);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax: TaxCalculator = {
      computeTaxCents: () => -50,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping: ShippingCalculator = {
      computeShippingCents: () => -50,
    };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to no discount, no tax, free shipping, US region", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3000);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(3000);
  });

  it("computes tax on discounted subtotal, not raw subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: (s) => Math.floor(s * 0.5),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn((taxable) => Math.floor(taxable * 0.1)),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();
    // 50% off 1000 = 500 discount → taxable = 500
    expect(tax.computeTaxCents).toHaveBeenCalledWith(500, "US");
  });
});

// ── Async checkout ─────────────────────────────────────────────────

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
