{"path": "/tmp/sv-8e6eca832f4e45d7b6ba1ccb7f8a9268/fixtures/typescript-vitest-cart/tests/cart.test.ts", "file_text": "import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const mkProduct = (
  id: string,
  priceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

// ── Cart line management ───────────────────────────────────────────

describe("Cart line management", () => {
  it("starts with 0 items and empty totals", () => {
    const cart = new Cart();
    expect(cart.itemCount).toBe(0);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("add() inserts a new line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    expect(cart.itemCount).toBe(2);
    expect(cart.totals().subtotalCents).toBe(2000);
  });

  it("add() merges quantity for the same product", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("a", 1000), 3);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5000);
  });

  it("add() rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", 100), 0)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 100), -1)).toThrow(RangeError);
    expect(() => cart.add(mkProduct("a", 100), 1.5)).toThrow(RangeError);
  });

  it("add() rejects negative unit price", () => {
    const cart = new Cart();
    expect(() => cart.add(mkProduct("a", -1), 1)).toThrow(RangeError);
  });

  it("remove() deletes an existing product and returns true", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove() returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity() changes line quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
    expect(cart.totals().subtotalCents).toBe(5000);
  });

  it("updateQuantity(0) removes the line", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity() throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("missing", 3)).toThrow("not in the cart");
  });

  it("updateQuantity() rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity() rejects non-integer quantity", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear() removes all lines", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("b", 500), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
    expect(cart.totals().subtotalCents).toBe(0);
  });

  it("snapshot() returns a deep copy", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const snap = cart.snapshot();
    // Mutating the snapshot should not affect the cart
    (snap as any)[0].quantity = 999;
    (snap as any)[0].product.unitPriceCents = 1;
    expect(cart.totals().subtotalCents).toBe(2000);
    expect(cart.itemCount).toBe(2);
  });
});

// ── Pricing pipeline ───────────────────────────────────────────────

describe("Cart pricing pipeline", () => {
  it("applies subtotal → discount → tax → shipping in order", () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const taxCalculator: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };

    const cart = new Cart({
      discountPolicy,
      taxCalculator,
      shippingCalculator,
      region: "US-CA",
    });

    cart.add(mkProduct("a", 1000), 1); // subtotal = 1000
    const t = cart.totals();

    // discount receives subtotal
    expect(discountPolicy.computeDiscountCents).toHaveBeenCalledWith(1000);
    // tax receives discounted subtotal (1000 - 200 = 800)
    expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    // shipping receives lines and discounted subtotal
    expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      800,
    );

    expect(t.subtotalCents).toBe(1000);
    expect(t.discountCents).toBe(200);
    expect(t.taxCents).toBe(80);
    expect(t.shippingCents).toBe(500);
    // total = discounted subtotal + tax + shipping = 800 + 80 + 500
    expect(t.totalCents).toBe(1380);
  });

  it("clamps discount to [0, subtotal]", () => {
    const overDiscount: DiscountPolicy = {
      computeDiscountCents: () => 99999,
    };
    const cart = new Cart({ discountPolicy: overDiscount });
    cart.add(mkProduct("a", 500), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(500); // clamped to subtotal
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negativeDiscount: DiscountPolicy = {
      computeDiscountCents: () => -100,
    };
    const cart = new Cart({ discountPolicy: negativeDiscount });
    cart.add(mkProduct("a", 500), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.totalCents).toBe(500);
  });

  it("clamps negative tax to 0", () => {
    const negativeTax: TaxCalculator = {
      computeTaxCents: () => -50,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const negativeShipping: ShippingCalculator = {
      computeShippingCents: () => -50,
    };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("defaults to no discount, no tax, free shipping, US region", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3000);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(3000);
  });

  it("computes tax on discounted subtotal, not raw subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: (s) => Math.floor(s * 0.5),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn((taxable) => Math.floor(taxable * 0.1)),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(mkProduct("a", 1000), 1);
    cart.totals();
    // 50% off 1000 = 500 discount → taxable = 500
    expect(tax.computeTaxCents).toHaveBeenCalledWith(500, "US");
  });
});

// ── Async checkout ─────────────────────────────────────────────────

describe("Cart.checkout()", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.product.id).toBe("a");
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });

    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("checks inventory and passes when available", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        reason: "discontinued",
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("discontinued");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 0,
    };
    const cart = new Cart({ discountPolicy: discount, region: "FR" });
    cart.add(mkProduct("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.2),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("FR");
    // 20% of 1000 = 200
    expect(result.totals.taxCents).toBe(200);
    expect(result.totals.totalCents).toBe(1200);
  });

  it("composes discount + async tax + shipping", async () => {
    const discountPolicy: DiscountPolicy = {
      computeDiscountCents: (s) => Math.floor(s * 0.1), // 10% off
    };
    const shippingCalculator: ShippingCalculator = {
      computeShippingCents: () => 500,
    };
    const cart = new Cart({ discountPolicy, shippingCalculator, region: "US" });
    cart.add(mkProduct("a", 2000), 1); // subtotal 2000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1), // 10% tax
    };

    const result = await cart.checkout({ asyncTaxProvider });
    // discount = 10% of 2000 = 200 → discounted = 1800
    // tax = 10% of 1800 = 180
    // shipping = 500
    // total = 1800 + 180 + 500 = 2480
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(180);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2480);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service failed")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service failed");
  });

  it("checks inventory for each line and first denial wins", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: true, availableQuantity: 5 })
        .mockResolvedValueOnce({ available: false, reason: "sold out" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });

  it("checkout with all collaborators combined", async () => {
    const cart = new Cart({ region: "DE" });
    cart.add(mkProduct("x", 500), 2); // old price 500 each

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.19),
    };

    const result = await cart.checkout({ priceFetcher, inventoryChecker, asyncTaxProvider });
    // new price = 600 × 2 = 1200 subtotal
    // no discount → discounted = 1200
    // 19% of 1200 = 228
    // free shipping (default)
    // total = 1200 + 228 = 1428
    expect(result.totals.subtotalCents).toBe(1200);
    expect(result.totals.taxCents).toBe(228);
    expect(result.totals.totalCents).toBe(1428);
    expect(result.lines[0]!.product.unitPriceCents).toBe(600);
  });
});
"}

